import httpx
import json


async def check_ueproxy_running_on_port(port: int) -> bool:
    """
    Check if another ueproxy is running locally on the given port asynchronously.
    :param port: Port number to check.
    :return: True if ueproxy is running on the port, False otherwise.
    """
    localhost = "127.0.0.1"
    url = f"http://{localhost}:{port}/"
    try:
        async with httpx.AsyncClient() as client:
            response = await client.get(url, timeout=1.0)
            if "plugins" in response.json():
                return True
            return False
    except (httpx.ConnectError, json.JSONDecodeError, httpx.ReadTimeout, httpx.ConnectTimeout):
        return False
